using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpRestServer;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor-injected via the DI container — no [FromServices] needed here.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_weather"),
     Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var weather = json.GetProperty("current_weather");

        return $"Temperature: {weather.GetProperty("temperature")}°C, "
             + $"Wind: {weather.GetProperty("windspeed")} km/h, "
             + $"Conditions code: {weather.GetProperty("weathercode")}";
    }

    [McpServerTool(Name = "get_elevation"),
     Description("Get the elevation in meters for a given coordinate.")]
    public async Task<string> GetElevationAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current_weather=true";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var elevation = json.GetProperty("elevation");

        return $"Elevation: {elevation} meters";
    }
}

